class Refund
  MAX_PERCENT = 100

  def initialize(order_total_cents:)
    @order_total_cents = order_total_cents
  end

  def amount_cents(percent)
    raise ArgumentError, "percent must be between 0 and #{MAX_PERCENT}" unless (0..MAX_PERCENT).cover?(percent)

    (@order_total_cents * percent / 100.0).round
  end
end

class Shop
  def total(items)
    items.sum { |item| item[:price] }
  end
end

